-- Restore the 1,690 terminus-maximus replays flipped to 'cluster' back to 'public'
-- (community content); a forward reversal of 20260904000000.
-- target-db: general
-- Scoped by explicit id list AND the database guard, never a predicate: another database
-- holds legitimately 'cluster' terminus rows.

BEGIN;

DO $guard$
BEGIN
  IF current_database() <> 'postgres' THEN
    RAISE EXCEPTION
      'PS-136: this migration targets the General database (postgres) only; refusing to run on %. Another database in this estate holds pre-existing cluster-scoped terminus-maximus rows that must NOT be flipped.',
      current_database();
  END IF;
END;
$guard$;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

