  f65dee62-fd4d-4a10-b4ed-f641cda8c3f0,f6858d2d-7aa3-4f1b-bbb0-a890d1ac28cb,f6d7c7d6-46e5-4f4e-a10a-5cfe2d04f6fa,f764af33-4632-4588-adcc-ecb42b4ac2b4,
  f79bf13f-646c-420e-918a-475a841ddb99,f7c59719-d59c-44c7-9760-8a3b6548e066,f7ee4200-b133-4242-ba18-51f2abbab08f,f7f4bf8e-9e4f-4f39-adfc-210e3babc4f3,
  f83281c6-3dd3-46a9-be9f-cf2fca4db4dc,f83c2b1f-9dee-4188-b9f9-ea38e1dd2680,f87de9ee-79f6-4ff3-bf69-3ff34d577387,f882cd19-71f5-4833-8a32-d9f255c4432f,
  f88f4d1b-d2b7-4f51-9886-92af3671c77b,f8a74f83-8baa-4f43-9bf5-4c9e05755b90,f91cbd59-992a-4cb3-8e87-f01d516c0c7e,f9305c84-4e6e-4413-86b9-66d24fd64b34,
  f94398b0-af8a-4611-8c64-27eaada8e46d,f947b7fe-745f-4758-9ca2-7b7685837867,f95838d3-8700-4e86-a587-25f77e08ad48,f9668d4b-6366-48e8-b542-3a51ea880bf1,
  f96a257e-488c-4d6e-bdd4-f00ae58e4576,f9a41f40-f9f2-48d0-b331-d1692494a3bd,f9adaeb2-f822-43e3-85d4-c6db7b6381c2,f9aeea5f-9a86-4fca-bd9d-5afe179d3fd6,
  f9fcf47f-9e28-482d-a146-a95890ccf0c3,fa1e125c-257a-4d10-a1d3-50eeb953f57a,fa4702cb-25e4-48f8-a6d9-3789f07b3987,fa6948d6-4161-44a6-adfa-b203ff073c30,
  fb0109ea-2113-4a34-bc91-4865f4093b8a,fb0ba043-ecff-4312-9227-eb3d2231868f,fb1eadce-08cd-46c5-b6d4-b9147e32059d,fb72bce4-9d68-4af0-ba34-f0dbb0e34eb1,
  fb82868a-0299-499d-a93e-90e84713e7e4,fbf16d4a-1ae2-4879-80d9-13c12705f5cc,fc47da7c-4a60-4c21-a6df-f1d7db14bcb8,fcaef358-9e8b-4594-87a8-b42d925d10d8,
  fcbbeb9d-fe72-4862-8adf-b75bcfe6ee6d,fd39d489-95e2-42c8-82a0-c63d2e40fc7b,fd5ac0d3-d679-41f2-9742-56834e15da4c,fd7267f3-e761-43df-ae61-2bde65b77230,
  fe1db39c-2029-4ca6-9d42-615fb2c275a6,fe268487-14c0-4d5b-8ca9-c0c48962fa35,fe340118-ff6d-4ef3-959a-dd5b7163dcc4,fe41efa6-8ffb-4b0f-9697-a04cf161f153,
  fe8db9bc-90b4-4427-8d67-a0b01691a5e6,ff06d1e9-81ab-426b-bea0-4684fac86989,ff33e8b7-73ed-496b-8eb9-b34ec73294ee,ff7312e4-e12d-4d08-9028-e9c9d9901196,
  ffa4a842-a82f-49e2-9712-9293f020c53a,fff44581-573b-4e0c-a715-462f29dd9af7
}'::uuid[];
  v_present   bigint;
  v_cluster   bigint;
  v_missing   bigint;
BEGIN
  IF to_regclass('public.boss_playbook_replays') IS NULL THEN
    RAISE EXCEPTION
      'PS-136 verify: relation public.boss_playbook_replays does not exist; this check cannot pass vacuously';
  END IF;

  IF array_length(v_ids, 1) <> v_expected THEN
    RAISE EXCEPTION
      'PS-136 verify: embedded id list holds % ids, expected %; the list has been edited',
      array_length(v_ids, 1), v_expected;
  END IF;

  SELECT count(*) INTO v_present
  FROM public.boss_playbook_replays
  WHERE id = ANY(v_ids);

  v_missing := v_expected - v_present;
  IF v_missing <> 0 THEN
    RAISE EXCEPTION
      'PS-136 verify: % of the % listed replay id(s) are not present in public.boss_playbook_replays; a wrong or truncated id list must not pass vacuously',
      v_missing, v_expected;
  END IF;

  SELECT count(*) INTO v_cluster
  FROM public.boss_playbook_replays
  WHERE id = ANY(v_ids)
    AND visibility = 'cluster';

  IF v_cluster > 0 THEN
    RAISE EXCEPTION
      'PS-136 verify: % of the % listed terminus-maximus replay row(s) are still visibility = cluster',
      v_cluster, v_expected;
  END IF;

  RAISE NOTICE
    'PS-136 verify: OK -- all % listed replay id(s) present, 0 with visibility = cluster',
    v_expected;
END
$verify$;

COMMIT;
